import{_ as t,o,c as i,a2 as a}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"ADR 0004 — Device bridge is a shared, versioned contract with sovereign-desktop","description":"","frontmatter":{"status":"Accepted","date":"2026-07-31T00:00:00.000Z","deciders":"kasunben","sourceUrl":"https://github.com/sovereignfs/sovereign-mobile/blob/main/docs/adrs/0004-shared-device-bridge-contract-with-desktop.md"},"headers":[],"relativePath":"apps/mobile/adrs/0004-shared-device-bridge-contract-with-desktop.md","filePath":"apps/mobile/adrs/0004-shared-device-bridge-contract-with-desktop.md"}'),s={name:"apps/mobile/adrs/0004-shared-device-bridge-contract-with-desktop.md"};function r(n,e,d,c,l,h){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0004-—-device-bridge-is-a-shared-versioned-contract-with-sovereign-desktop" tabindex="-1">ADR 0004 — Device bridge is a shared, versioned contract with <code>sovereign-desktop</code> <a class="header-anchor" href="#adr-0004-—-device-bridge-is-a-shared-versioned-contract-with-sovereign-desktop" aria-label="Permalink to &quot;ADR 0004 — Device bridge is a shared, versioned contract with `sovereign-desktop`&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted. Protocol owned and designed in sovereign RFC 0083; this ADR records this repo&#39;s commitment to consuming it rather than defining its own.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Both this repo and <code>sovereign-desktop</code> need to expose native device capabilities (geolocation, camera, calendar, NFC, haptics, push, and future capabilities) to plugin authors through the same portable <code>sdk.device.*</code> call surface. If each shell repository designed its own bridge protocol independently, the two would drift the first time a capability shipped to only one of them — and plugin authors would be back to branching on shell internals, the exact thing <code>sdk.device.*</code> exists to prevent.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>This repo implements the <strong>Capacitor transport</strong> of a single, published, versioned contract owned centrally: <code>@sovereignfs/bridge</code> (implementation: transports, protocol, shell-side helper) plus <code>@sovereignfs/sdk/device-client</code> (contract: capability registry, types, <code>provideBridge()</code>), both defined and published from the <code>sovereign</code> monorepo per sovereign RFC 0083. <code>sovereign-desktop</code> implements the Tauri transport of the same contract.</p><p>Capability negotiation happens at handshake: the shell announces exactly which capabilities it supports and at which version. Plugins call <code>supports(&#39;haptics.impact&#39;, 1)</code>; <strong>no code anywhere compares shell versions.</strong> Results are a typed discriminated union — <code>available</code>, <code>denied</code>, <code>dismissed</code>, <code>unavailable</code> — never a thrown exception, so a plugin can tell &quot;the user said no&quot; from &quot;this device doesn&#39;t have it&quot; from &quot;this shell hasn&#39;t implemented it yet.&quot;</p><h2 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to &quot;Rejected alternatives&quot;">​</a></h2><ul><li><strong>A bridge designed independently in this repo.</strong> Would let this shell and <code>sovereign-desktop</code> diverge on the first capability either one shipped — exactly the failure mode RFC 0083 exists to close off.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>This repo must expose <strong>only</strong> the narrow bridge object to page JS — <strong>never</strong> raw <code>window.Capacitor</code>. Page content (the platform, and any plugin it hosts) reaches native capability exclusively through the published bridge surface.</li><li>This shell&#39;s advertised <code>capabilities</code> list at handshake must reflect exactly what this build actually implements — never aspirational, never stale.</li><li>v1 ships RFC 0083&#39;s deliberately thin slice: <code>haptics.impact</code> and <code>notifications.native</code>, plus a platform-internal <code>secureStorage</code> tier. Broader capabilities (camera, calendar, NFC, geolocation, biometrics — see <a href="./../research/0002-device-capability-candidates.html">docs/research/0002-device-capability-candidates.md</a>) land later as additive registry entries against the same contract, not as new mechanisms.</li><li>New <code>device:*</code> manifest permissions and per-user consent grants are owned by the platform (<code>packages/manifest</code>, <code>runtime</code>, <code>plugins/account</code>), not by this repo — this repo implements the transport, not the permission or consent model.</li><li>Protocol changes are made in <code>sovereign</code>, not here. A capability this shell needs that the contract doesn&#39;t yet define is a <code>sovereign</code> PR first, a <code>sovereign-mobile</code> PR second.</li></ul>',12)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
